// 📊 COLLECTEUR - Accès correct aux données webhook
const webhookData = $input.item.json.body;

console.log('📊 WEBHOOK - ACCÈS CORRECT:');
console.log('- Données body présentes:', !!webhookData);
console.log('- Type:', typeof webhookData);
console.log('- Keys:', webhookData ? Object.keys(webhookData) : 'null');
console.log('- Contenu preview:', webhookData?.contenu?.substring(0, 100));

// Vérification structure
if (!webhookData || typeof webhookData !== 'object') {
  throw new Error('webhookData invalide - structure: ' + JSON.stringify($input.item.json));
}

if (!webhookData.contenu) {
  throw new Error('Champ contenu manquant - clés: ' + Object.keys(webhookData).join(', '));
}

// Préserver les données webhook + binary
const result = {
  json: {
    // Données webhook originales
    contenu_original: webhookData.contenu,
    subtitle_original: webhookData.subtitle || '',

    // Métadonnées
    timestamp: new Date().toISOString(),
    collecteur_status: 'webhook_data_extracted',

    // Debug
    debug: {
      webhook_structure: Object.keys($input.item.json),
      body_structure: Object.keys(webhookData),
      contenu_length: webhookData.contenu.length
    }
  },
  binary: $input.item.binary || {}
};

console.log('✅ COLLECTEUR SUCCESS:');
console.log('- Contenu extrait:', result.json.contenu_original.length, 'caractères');
console.log('- Binary préservé:', Object.keys(result.binary).length, 'items');

return result;

// 🔗 FUSION - Méthode sûre basée sur le workflow fonctionnel
const allInputs = $input.all();
console.log('🔗 FUSION - ANALYSE INPUTS:', allInputs.length);

// Identifier les données par leur structure
let collectorData = null;
let openAIData = null;

allInputs.forEach((input, index) => {
  console.log(`Input ${index}:`, {
    hasJson: !!input.json,
    isCollector: !!(input.json?.collecteur_status),
    isOpenAI: !!(input.json && Array.isArray(input.json) && input.json[0]?.message),
    keys: input.json ? Object.keys(input.json) : []
  });

  // Collecteur = contient collecteur_status
  if (input.json?.collecteur_status === 'webhook_data_extracted') {
    collectorData = input;
    console.log('✅ COLLECTEUR TROUVÉ');
  }

  // OpenAI = structure array avec message (comme workflow fonctionnel)
  if (Array.isArray(input.json) && input.json[0]?.message?.content) {
    openAIData = input;
    console.log('✅ OPENAI TROUVÉ');
  }
});

// Validation
if (!collectorData) {
  throw new Error('Données collecteur manquantes');
}

// Parse OpenAI (méthode du workflow fonctionnel)
let aiTitle = 'Titre par défaut';
let aiSubtitle = 'Sous-titre par défaut';
let aiBody = collectorData.json.contenu_original;

if (openAIData && openAIData.json[0]?.message?.content) {
  const aiResponse = openAIData.json[0].message.content;
  console.log('🤖 AI RESPONSE BRUT:', aiResponse.substring(0, 200));

  try {
    // Nettoyage comme dans le workflow fonctionnel
    const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
    const analysis = JSON.parse(cleanResponse);

    aiTitle = analysis.title || aiTitle;
    aiSubtitle = analysis.subtitle || aiSubtitle;
    aiBody = analysis.body || aiBody;

    console.log('✅ IA PARSING SUCCESS:', { title: aiTitle, subtitle: aiSubtitle });
  } catch (e) {
    console.log('❌ IA PARSING FAILED:', e.message);
  }
} else {
  console.log('⚠️ OpenAI data manquante - utilisation valeurs par défaut');
}

// Résultat final
const result = {
  json: {
    // Données originales
    contenu_original: collectorData.json.contenu_original,
    subtitle_original: collectorData.json.subtitle_original,

    // Données IA analysées
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,

    // Debug complet
    debug: {
      inputs_count: allInputs.length,
      collector_found: !!collectorData,
      openai_found: !!openAIData,
      ai_parsing_success: aiTitle !== 'Titre par défaut',
      binary_preserved: !!(collectorData.binary && Object.keys(collectorData.binary).length > 0),
      binary_count: collectorData.binary ? Object.keys(collectorData.binary).length : 0
    }
  },
  binary: collectorData.binary || {}
};

console.log('🎯 FUSION RESULT:');
console.log('- AI Title:', result.json.ai_title);
console.log('- Binary preserved:', result.json.debug.binary_preserved);
console.log('- Binary count:', result.json.debug.binary_count);

return result;

// ✅ RÉSULTAT FINAL - Style workflow fonctionnel
const flaskResponse = $input.item.json;
const fusionData = $input.first();

console.log('✅ RÉSULTAT FINAL:');
console.log('- Flask success:', !!flaskResponse?.success);
console.log('- Project ID:', flaskResponse?.project_id);
console.log('- AI data:', fusionData?.json?.debug);

if (flaskResponse?.success) {
  return {
    json: {
      status: 'success',
      message: '🎉 Document InDesign créé avec IA + images !',
      project_id: flaskResponse.project_id,
      download_url: `http://host.docker.internal:5003/api/download/${flaskResponse.project_id}`,

      details: {
        ai_analysis: {
          title: fusionData?.json?.ai_title,
          subtitle: fusionData?.json?.ai_subtitle,
          body_preview: fusionData?.json?.ai_body?.substring(0, 100) + '...'
        },
        technical: {
          ai_parsing_success: fusionData?.json?.debug?.ai_parsing_success,
          binary_preserved: fusionData?.json?.debug?.binary_preserved,
          binary_count: fusionData?.json?.debug?.binary_count
        }
      }
    }
  };
} else {
  return {
    json: {
      status: 'error',
      message: '❌ Erreur création document',
      error: flaskResponse?.error || 'Erreur inconnue',
      debug: {
        flask_response: flaskResponse,
        fusion_debug: fusionData?.json?.debug
      }
    }
  };
}
